/**
 * NAMI CMS — Documents & Publications
 *
 * Requires the "NAMI CMS — Core engine" snippet, version 1.2.0 or later
 * (collections). Adds a "Documents" menu:
 *   - All Documents / Add New: each downloadable file on /documents
 *     (forms, books, brochures …).
 *   - Page: …: the heading, the category tabs, the empty-search message and
 *     the "apply online" banner.
 *
 * Field keys must match src/lib/cms/pages/documents/types.ts in the Next.js project.
 * The JSON blocks at the bottom are generated by `npm run cms:defaults`.
 */

if ( ! defined( 'ABSPATH' ) ) {
	return;
}

/** Category choices come from Documents → Page: Categories. */
function nami_documents_category_options() {
	$options = array();
	if ( function_exists( 'nami_cms_get_values' ) ) {
		$values = nami_cms_get_values( 'documents' );
		$items  = $values['categories']['items'] ?? array();
		foreach ( is_array( $items ) ? $items : array() as $item ) {
			$key = trim( (string) ( $item['key'] ?? '' ) );
			if ( '' !== $key ) {
				$options[ $key ] = (string) ( $item['label'] ?? $key );
			}
		}
	}
	return empty( $options ) ? array( '' => '— Add categories under Documents → Page: Categories —' ) : $options;
}

