// Fill in the file size from the upload when it was left empty. Runs after the
// core engine has saved the fields (priority 10) and before it refreshes the
// website (priority 99).
add_action(
	'save_post_nami_document',
	function ( $post_id ) {
		if ( wp_is_post_revision( $post_id ) ) {
			return;
		}
		$fields = get_post_meta( $post_id, '_nami_fields', true );
		if ( ! is_array( $fields ) || '' !== trim( (string) ( $fields['fileSize'] ?? '' ) ) ) {
			return;
		}
		$attachment = attachment_url_to_postid( (string) ( $fields['file'] ?? '' ) );
		$path       = $attachment ? get_attached_file( $attachment ) : '';
		if ( ! $path || ! file_exists( $path ) ) {
			return;
		}
		$fields['fileSize'] = size_format( filesize( $path ), 2 );
		update_post_meta( $post_id, '_nami_fields', wp_slash( $fields ) );
	},
	20
);
